head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF41095.xml";
scwin.processGp;
scwin.vRowCount = 0;
scwin.confirmYn = 0;
scwin.vSetCntrCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = ""; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/******************************************************************* 
 * 함수명   : fn_SetSrtyCombo
 * 설명     : 콤보데이터를 설정한다.
 * argument : vScrenID, dtsObj, CD_ID_M
 *******************************************************************/
scwin.fn_SetSrtyCombo = function(vScrenID, dtsObj, CD_ID_M) {
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ID_M='CNTR_CD'";
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};


/********************************************** 
 * 설명       : 보증인관리 목록조회
 ***********************************************/
scwin.fn_list_search = function() {
    var vSrtyStatusCd = $c.stf.getObjectValue(cmb_sch_srty_stat_cd);
    if (vSrtyStatusCd == "A") {
        vSrtyStatusCd = '';
    } else if (vSrtyStatusCd == "B") {
        vSrtyStatusCd = 0;
    } else if (vSrtyStatusCd == "C") {
        vSrtyStatusCd = 1;
    }
    var url = "/etn/EtnLstSprt.do?method=searchSrtyList";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&outputMessageId=ETN_SRTY_LIST";
    url += "&COM_NM=" + txb_com_abbrv.getValue();
    url += "&APPL_PROCS_TP_CD=" + vSrtyStatusCd;
    dts_List_1.DataID = encodeURI(url);
    dts_List_1.Reset();

    //ShowWin(grd_List);
    return url;
};


/********************************************** 
 * 설명       : 보증인관리 상세조회
 ***********************************************/
scwin.fn_searchDetail = function(row) {
    var url = "/etn/EtnLstSprt.do?method=searchSrtyDtl";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&outputMessageId=ETN_SRTY_LISTDETAIL";
    url += "&SRTY_CD=" + dts_List_1.getCellData(row, "SRTY_CD");
    dts_List_2.DataID = encodeURI(url);
    dts_List_2.Reset();
    var gubun = dts_List_1.getCellData(row, "APPL_PROCS_TP_NM");
    if (gubun == "승인" || gubun == undefined) {
        btn_confirm.setDisabled(true);
        btn_confirm.src = "../img/btn_approval_d.gif";
        btn_return.setDisabled(true);
        btn_return.src = "../img/btn_Ret_d.gif";
    } else {
        btn_confirm.setDisabled(false);
        btn_confirm.src = "../img/btn_approval.gif";
        btn_return.setDisabled(false);
        btn_return.src = "../img/btn_Ret.gif";
    }
    return url;
};



/********************************************** 
 * 설명       : 보증인관리 코드존재여부 체크
 ***********************************************/
scwin.fn_chkSrtyCd = function() {
    var url = "/etn/EtnLstSprt.do?method=searchSrtyDtl";
    url += "&outputMessageId=ETN_SRTY_LISTDETAIL";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRTY_CD=" + $c.stf.getObjectValue(edt_srty_cd); // 			

    dts_ChkCd.DataID = encodeURI(url);
    dts_ChkCd.Reset();
    if (dts_ChkCd.getCellData(0, "SRTY_CD") == null) {
        return false;
    } else {
        return true;
    }
};




/********************************************** 
 * 설명       : 보증인정보 수정
 ***********************************************/
scwin.fn_Update = function(gubun) {
    scwin.confirmYn = gubun;
    if (scwin.confirmYn == 1) {
        if (!window.confirm($c.stf.getMessageParam("MSG-A006", "승인"))) return;
    } else if (scwin.confirmYn == 2) {
        if (!window.confirm($c.stf.getMessageParam("MSG-A006", "반송"))) return;
    }
    var url = "/etn/EtnLstSprt.do?method=saveSrtyDtl";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    dts_List_2.setCellData(1, "APPL_PROCS_TP_CD", scwin.confirmYn);
    trs_save.Action = $c.lce.fn_encodeNSession(url);
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List_2)";
    trs_save.Post();
};


/********************************************** 
 * 설명       : 보증인정보 Validation
 ***********************************************/
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(edt_srty_cd) == "") {
        $c.win.alert("보증인코드를 입력하세요");
        edt_srty_cd.focus();
        return false;
    }
    if (!$c.lce.fn_getCheckByte('보증인코드', $c.stf.getObjectValue(edt_srty_cd), 5)) return false;
    if ($c.stf.getObjectValue(txb_srty_nm) == "") {
        $c.win.alert("[보증인명]을 입력하세요.");
        txb_srty_nm.focus();
        return false;
    }
    if (!$c.lce.fn_getCheckByte('보증인명', $c.stf.getObjectValue(txb_srty_nm), 100)) return false;
    if (!$c.lce.fn_getCheckByte('보증인약명', $c.stf.getObjectValue(txb_srty_abbrv), 50)) return false;
    var pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    var str = $c.stf.getObjectValue(txb_srty_eng_nm);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문보증인명에 한글은 사용할 수 없습니다');
            txb_srty_eng_nm.focus();
            return false;
        }
    }
    if (!$c.lce.fn_getCheckByte('영문보증인명', $c.stf.getObjectValue(txb_srty_eng_nm), 100)) return false;
    var str = $c.stf.getObjectValue(txb_srty_eng_abbrv);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문보증인약명에 한글은 사용할 수 없습니다');
            txb_srty_eng_abbrv.focus();
            return false;
        }
    }
    if (!$c.lce.fn_getCheckByte('영문보증인약명', $c.stf.getObjectValue(txb_srty_eng_abbrv), 50)) return false;

    //자리수 체크
    if (!$c.lce.fn_getCheckByte('주소', $c.stf.getObjectValue(txb_addr), 200)) return false;
    if (!$c.lce.fn_getCheckByte('보증인종류', $c.stf.getObjectValue(txb_srty_kind_contn), 40)) return false;
    return true;
};


/********************************************** 
 * 함수명   : fn_GetParSrty
 * 설명       : 보증인 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParSrty = function(arrPar) {
    arrPar[0] = {
        SRTY_CD: $c.stf.getObjectValue(txb_isur_cd),
        SRTY_NM: $c.stf.getObjectValue(txb_com_abbrv)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParSrty
 * 설명       : 보증인 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParSrty = function(arrPar) {
    if (typeof(arrPar[0].SRTY_CD) != 'undefined') {
        txb_isur_cd.setValue(arrPar[0].SRTY_CD);
        txb_com_abbrv.setValue(arrPar[0].SRTY_NM);
    }
};
scwin.gform_onload = function() {
    /********************************************** 
     * 함수명   : gform > onload
     * 설명      : 화면 Onload
     ***********************************************/
    $c.cm.PanelToGroupBox(panel_Top);
    //PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);

    //데이터셋 초기화
    dts_List_1.DataID = "/etn/EtnLstSprt.do?method=searchSrtyList&messageId=ETN_SRTY_LIST";
    dts_List_1.reset();
    dts_List_2.DataID = "/etn/EtnLstSprt.do?method=searchSrtyDtl&messageId=ETN_SRTY_LISTDETAIL";
    dts_List_2.reset();

    // 버튼 세팅
    btn_confirm.setDisabled(true);
    btn_confirm.src = "../img/btn_approval_d.gif";
    btn_return.setDisabled(true);
    btn_return.src = "../img/btn_Ret_d.gif";
};
scwin.btn_Search_onclick = function() {
    /********************************************** 
     * Event   : btn_Search > OnClick
     * 설명    : 조회버튼 클릭
     ***********************************************/
    // 보증인 목록조회
    scwin.fn_list_search();
    if (scwin.vSetCntrCd != 1) {
        $c.lce.fn_SetSrtyCombo(scwin.vScrenID, dts_Cntrcd, '01371'); //국가 01371
        scwin.vSetCntrCd = 1;
    }
};
scwin.img_com_srch_onclick = function() {
    /********************************************** 
     * Event   : img_com_srch > OnClick
     * 설명    : 발행기관 조회팝업
     ***********************************************/
    fn_GetPar = fn_GetParSrty;
    fn_SetPar = fn_SetParSrty;
    $c.lce.fn_PopSrtySearch(img_com_srch);
};
scwin.txb_isur_cd_onblur = function() {
    /********************************************** 
     * 함수명   : txb_ISUR_CD > onblur
     * 설명      : 발행기관 코드 변경
     ***********************************************/
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.btn_confirm_onclick = function() {
    /********************************************** 
     * Event   : btn_confirm > OnClick
     * 설명    : 승인버튼 클릭
     ***********************************************/
    scwin.processGp = SCREN_PROCS_TP_CD_03;
    scwin.fn_Update(1);
};
scwin.btn_return_onclick = function() {
    /********************************************** 
     * Event   : btn_return > OnClick
     * 설명    : 반송버튼 클릭
     ***********************************************/
    scwin.processGp = SCREN_PROCS_TP_CD_03;
    scwin.fn_Update(2);
};
scwin.txb_isur_cd_onblur = function() {
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.dts_List_1_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_List_1 > OnLoadError
     * 설명    : dts_List_1 조회에러시 처리
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_2_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_List_2 > OnLoadError
     * 설명    : dts_List_2 조회에러시 처리
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * Event   : dts_List_2 > OnLoadCompleted
     * 설명    : dts_List_2 조회성공시 처리
     ***********************************************/
    edt_srty_cd.setDisabled(true);
};
scwin.dts_ChkCd_OnLoadError = function() {
    /********************************************** 
     * Event   : dts_ChkCd > OnLoadError
     * 설명    : dts_ChkCd 조회에러시 처리
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_ChkCd_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * Event   : dts_ChkCd > OnLoadCompleted
     * 설명    : dts_ChkCd 조회성공시 처리
     ***********************************************/
};
scwin.trs_save_OnFail = function() {
    /********************************************** 
     * Event   : trs_save > OnFail
     * 설명    : 저장 에러시 처리
     ***********************************************/
    if (scwin.processGp == SCREN_PROCS_TP_CD_03) {
        if (scwin.confirmYn == 1) {
            $c.win.alert($c.stf.getMessageParam("MSG-A002", "승인"));
        } else if (scwin.confirmYn == 2) {
            $c.win.alert($c.stf.getMessageParam("MSG-A002", "반송"));
        }
    }
};
scwin.trs_save_OnSuccess = function() {
    /********************************************** 
     * Event   : trs_save > OnSuccess
     * 설명    : 저장 성공시 처리
     ***********************************************/
    // 버튼 세팅
    btn_confirm.setDisabled(false);
    btn_confirm.src = "../img/btn_approval_d.gif";
    btn_return.setDisabled(false);
    btn_return.src = "../img/btn_Ret_d.gif";

    //메세지처리
    //alert(getMessageParam("MSG-0001"));
    // 조회
    scwin.fn_list_search();
};
scwin.dts_List_1_OnRowPosChanged = function(row) {
    /********************************************** 
     * Event   : dts_List_1 > OnRowPosChanged
     * 설명    : 그리드 위치 변경시 세팅
     ***********************************************/
    scwin.fn_searchDetail(row);
};
